mapper.select:
SELECT f.*, p.pet_name, u.username FROM foster_return f LEFT JOIN pet p ON f.pet_id = p.pet_id LEFT JOIN user u ON f.user_id = u.user_id
AND f.status = #{status}
ORDER BY f.apply_time DESC

mapper.update:
UPDATE foster_return
SET status = #{status}, audit_opinion = #{auditOpinion}, audit_admin = #{auditAdmin}, audit_time = NOW()
WHERE return_id = #{returnId}
